effect.shader:
void main(){
vec2 uv=acScreenNorm,grid=vec2(max(blocks,1.0));
vec2 id=floor(uv*grid), center=(id+0.5)/grid, local=fract(uv*grid)-0.5;
vec4 tile=texture2DCv(inputImg.texture,clamp(center,0.0,1.0));
float lum=dot(tile.rgb,vec3(0.299,0.587,0.114));
float z=(lum-0.5)*depth;
vec2 q=uv-(center-0.5)*z*parallax/max(blocks,1.0);
vec4 raised=texture2DCv(inputImg.texture,clamp(q,0.0,1.0));
float edge=max(abs(local.x),abs(local.y));
float bevelMask=smoothstep(0.5-bevel,0.5,edge);
float faceLight=clamp(0.82+z*0.28,0.35,1.35);
float sideLight=mix(faceLight,0.38+0.25*step(0.0,local.x+local.y),bevelMask*lighting);
raised.rgb*=mix(1.0,sideLight,lighting);
vec4 src=texture2DCv(inputImg.texture,uv);
gl_FragColor=mix(src,raised,mixAmount);
}
